import{_ as a,o,c as s,a3 as r}from"./chunks/framework.BFeCKmyl.js";const u=JSON.parse('{"title":"Ações em lote nos lembretes","description":"","frontmatter":{"title":"Ações em lote nos lembretes","id":"eproc-lembretes-acoes-em-lote","plataforma":"eproc","grupo":"Destaques e lembretes","plano":"free","desde":"1.7.0","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-lembretes-acoes-em-lote.md","filePath":"funcionalidades/eproc-lembretes-acoes-em-lote.md"}'),t={name:"funcionalidades/eproc-lembretes-acoes-em-lote.md"};function l(i,e,c,n,m,d){return o(),s("div",null,e[0]||(e[0]=[r('<h1 id="acoes-em-lote-nos-lembretes" tabindex="-1">Ações em lote nos lembretes <a class="header-anchor" href="#acoes-em-lote-nos-lembretes" aria-label="Permalink to &quot;Ações em lote nos lembretes&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Permite marcar vários lembretes do processo e desativá-los de uma vez, com uma única confirmação, em vez de um por um.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, página do processo, lista de lembretes.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Passe o mouse sobre um lembrete. Aparece uma caixa de seleção (&quot;Selecionar lembrete&quot;).</li><li>Marque os lembretes que quer desativar. Cada lembrete marcado ganha um contorno azul em destaque. Uma barra acima da lista oferece <strong>Selecionar todos</strong> e <strong>Desativar selecionados</strong>.</li><li>Clique em <strong>Desativar selecionados</strong> e confirme. O eploc desativa os lembretes um a um, usando o próprio botão de lixeira do eproc.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Só aparece quando há mais de um lembrete.</li><li>Só os lembretes que você pode desativar (os que têm o ícone de lixeira) recebem a caixa de seleção.</li><li>A desativação é a mesma do eproc: depois de confirmada, não há como desfazer pelo eploc.</li></ul>',11)]))}const b=a(t,[["render",l]]);export{u as __pageData,b as default};
